//! The identifier of a context source registration (NGSI-LD clause 5.2.9).

uri_identifier!(
    /// The identifier of a context source registration: a URI (NGSI-LD clause 5.2.9), chosen by the registrant or
    /// generated by the broker when the registration is created without one (clause 5.9.2.4).
    ///
    /// ```
    /// use iri_rs::iri;
    /// use ngsi_ld::registration::RegistrationId;
    ///
    /// let id = RegistrationId::from(iri!("urn:ngsi-ld:ContextSourceRegistration:csr1a3456"));
    /// assert_eq!(
    ///     id,
    ///     "urn:ngsi-ld:ContextSourceRegistration:csr1a3456".parse::<RegistrationId>()?
    /// );
    /// # Ok::<(), anyhow::Error>(())
    /// ```
    RegistrationId
);
